/*
 * prog38_continued_fraction – reconstructed from the obfuscated binary.
 *
 * Behaviour (as observed from the original program):
 *
 *   * If the program is invoked with fewer than two arguments
 *     (i.e. argc < 3) it prints
 *
 *           NO_INPUT
 *
 *   * It expects two signed decimal integers on the command line.
 *     If either argument cannot be parsed as an integer, or the
 *     second integer (the denominator) is zero, it prints
 *
 *           BAD_INPUT
 *
 *   * If the absolute value of either integer is larger than 100 000
 *     it prints
 *
 *           OUT_OF_RANGE
 *
 *   * The program then computes the (regular) continued‑fraction
 *     representation of the rational number a / b (a = first argument,
 *     b = second argument) using the Euclidean algorithm.
 *
 *   * The representation is printed in the usual bracketed form:
 *
 *           [q0; q1, q2, ...]
 *
 *     where the first term is printed directly after the opening '[',
 *     a semicolon and a space separate the first and second term,
 *     commas and spaces separate the remaining terms, and a closing
 *     bracket followed by a newline terminates the output.
 *
 *   * If more than 199 terms would be required, the program prints
 *
 *           ERROR
 *
 *     instead of a continued fraction.
 *
 *   * All output is terminated with a newline (the original used
 *     `puts` for the final bracket and for the error messages).
 *
 * The implementation below follows exactly this specification.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_TERMS 199
#define LIMIT 100000L

int main(int argc, char *argv[])
{
    /* ---------- 1. Argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- 2. Parse the two integers ---------- */
    char *endptr;
    long long a, b;

    errno = 0;
    a = strtoll(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    b = strtoll(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0' || b == 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- 3. Range check ---------- */
    if (llabs(a) > LIMIT || llabs(b) > LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- 4. Compute continued‑fraction terms ---------- */
    long long terms[MAX_TERMS + 1];   /* +1 to detect overflow */
    int count = 0;

    long long num = a;
    long long den = b;

    while (den != 0) {
        if (count > MAX_TERMS) {
            puts("ERROR");
            return 0;
        }
        long long q = num / den;          /* truncates toward 0 */
        long long r = num % den;
        terms[count++] = q;
        num = den;
        den = r;
    }

    /* ---------- 5. Output in the required format ---------- */
    putchar('[');
    if (count > 0) {
        printf("%lld", terms[0]);
        for (int i = 1; i < count; ++i) {
            if (i == 1)
                printf("; ");
            else
                printf(", ");
            printf("%lld", terms[i]);
        }
    }
    puts("]");
    return 0;
}
